import { createRequire } from 'node:module';
import assert from 'node:assert/strict';
const { chromium } = createRequire(import.meta.url)('playwright');
const [base, executablePath, token, sid] = process.argv.slice(2);
const browser = await chromium.launch({ executablePath, headless: true });
const context = await browser.newContext({ viewport: { width: 390, height: 844 } });
try {
  assert.equal((await context.request.post(base+'/api/login',{data:{token}})).status(),200);
  const initial = await (await context.request.get(base+'/__proposal')).json();
  const [p1] = initial.state.proposals.map(p=>p.id);
  const page=await context.newPage(); const sent=[];
  page.on('request',(r)=>{ if(r.method()==='POST' && r.url().endsWith('/say')) sent.push(r.postDataJSON()); });
  await page.goto(base+'/#demo/chat/'+sid);
  const first = () => page.getByLabel('Подтвердить разбор XR-4', {exact:true});
  const second = () => page.getByLabel('Подтвердить разбор XR-5', {exact:true});
  await first().waitFor(); await second().waitFor();
  assert.equal(await page.locator('.askfb input.caskpick').count(),2);
  await page.locator('.askfb').filter({hasText:'устарело'}).waitFor();
  await page.locator('.askfb a[href="#demo/draft/XR-4"]').waitFor();
  assert.equal(await page.locator('.askfb a[href*="/prepared/"]').count(),0,'операции показаны ссылками задач');
  // Свободный текст остаётся обсуждением даже при ранее отмеченном согласии.
  await first().check();
  const ta=page.locator('textarea.csay'); await ta.fill('почему такой исход?');
  await page.reload(); await first().waitFor(); assert.equal(await ta.inputValue(),'почему такой исход?');
  let response=page.waitForResponse(r=>r.url().endsWith('/say') && r.request().method()==='POST');
  await page.getByRole('button',{name:'Отправить',exact:true}).click();
  { const reply = await response; assert.equal(reply.status(),200,await reply.text()); }
  assert.equal(sent[0].proposal.mode,'comment'); assert.equal(sent[0].proposal.decisions.length,0);
  let view=await (await context.request.get(base+'/__proposal')).json();
  assert.ok(view.state.proposals.every(p=>!p.status));
  await page.reload(); await first().waitFor(); assert.equal(await first().isChecked(),false);
  await first().check(); await second().check();
  await page.reload(); await first().waitFor();
  assert.equal(await first().isChecked(),true); assert.equal(await second().isChecked(),true);
  assert.equal((await context.request.get(base+'/__delivery?mode=break')).status(),200);
  response=page.waitForResponse(r=>r.url().endsWith('/say') && r.request().method()==='POST');
  await page.getByRole('button',{name:'Отправить',exact:true}).click(); assert.equal((await response).status(),502);
  const answer=sent.at(-1).proposal;
  assert.equal(answer.decisions.length,3);
  assert.ok(answer.snapshots.every(s=>s.revision>0));
  view=await (await context.request.get(base+'/__proposal')).json();
  assert.ok(view.state.proposals.every(p=>p.status==='accepted')); assert.equal(view.state.state,'history');
  view=await (await context.request.get(base+'/__proposal?id=XR-5')).json();
  assert.equal(view.state.proposals[0].status,'accepted'); assert.equal(view.state.state,'history');
  assert.equal((await context.request.get(base+'/__delivery?mode=restore')).status(),200);
  await page.reload(); await page.locator('textarea.csay').waitFor();
  response=page.waitForResponse(r=>r.url().endsWith('/say') && r.request().method()==='POST' && r.status()===200);
  await page.evaluate(()=>window.dispatchEvent(new Event('online'))); await response;
  view=await (await context.request.get(base+'/__proposal')).json();
  assert.ok(view.state.proposals.every(p=>p.status==='accepted'));
  await page.reload(); await page.locator('.msg.me .proposal-attachment').filter({hasText:p1}).first().waitFor();
  assert.equal(await page.locator('.askresume').count(),0);
  assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);
  console.log(JSON.stringify({comment:true,refresh:true,whole:true,retry:true,conclusion:true,actionsOnly:true,taskLinks:0,mobile:390}));
} finally { await context.close(); await browser.close(); }
